package net.civeira.phylax.feature.oauth.delegatelogin.domain;

import java.util.Optional;

import lombok.Builder;
import lombok.Getter;
import lombok.NonNull;
import lombok.ToString;

/**
 * Identity asserted by an external provider after its response has been validated.
 *
 * Responsibilities: - Carry the stable provider subject used to link accounts. - Carry the email
 * and whether the provider verified it.
 *
 * Design notes: - The subject is the only key for linked accounts; the name is informative and
 * never selects an account. - Built only by providers, after checking signature or code exchange.
 */
@Getter
@Builder
@ToString
public class FederatedUser {
  /**
   * Stable identifier of the user at the provider (Google {@code sub}, SAML {@code NameID}).
   */
  @NonNull
  private final String subject;
  /**
   * Email asserted by the provider, if any.
   */
  private final String email;
  /**
   * Whether the provider states that the email belongs to the user.
   */
  private final boolean emailVerified;
  /**
   * Display name, for information only.
   */
  private final String name;

  /**
   * Returns the asserted email, if present and not blank.
   *
   * @return optional email
   */
  public Optional<String> email() {
    return Optional.ofNullable(email).map(String::trim).filter(value -> !value.isEmpty());
  }
}
